import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

tensor_matrix_mul_cpp = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void tensor_matrix_mul_kernel(const float* A, const float* B, float* C,
                                         int N, int M, int K, int L) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * M * L;
    if (idx < total) {
        int l = idx % L;
        int m = (idx / L) % M;
        int n = idx / (L * M);
        float sum = 0.0f;
        for (int k = 0; k < K; k++) {
            sum += A[n * M * K + m * K + k] * B[k * L + l];
        }
        C[n * M * L + m * L + l] = sum;
    }
}

torch::Tensor tensor_matrix_mul_cuda(torch::Tensor A, torch::Tensor B) {
    auto A_ = A.contiguous();
    auto B_ = B.contiguous();
    int N = A_.size(0);
    int M = A_.size(1);
    int K = A_.size(2);
    int L = B_.size(1);

    auto options = torch::TensorOptions().dtype(A_.dtype()).device(A_.device());
    auto out = torch::empty({N, M, L}, options);

    int total = N * M * L;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    tensor_matrix_mul_kernel<<<gridSize, blockSize>>>(
        A_.data_ptr<float>(),
        B_.data_ptr<float>(),
        out.data_ptr<float>(),
        N, M, K, L
    );
    return out;
}
"""

tensor_matrix_mul_header = r"""
torch::Tensor tensor_matrix_mul_cuda(torch::Tensor A, torch::Tensor B);
"""

tensor_matrix_mul = load_inline(
    name="tensor_matrix_mul",
    cpp_sources=tensor_matrix_mul_header,
    cuda_sources=tensor_matrix_mul_cpp,
    functions=["tensor_matrix_mul_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        return tensor_matrix_mul.tensor_matrix_mul_cuda(A, B)

